#!/bin/sh export LANG=en_US.UTF-8 [ -z "${vlpt+x}" ] || vlp=yes [ -z "${vmpt+x}" ] || { vmp=yes; vmag=yes; } [ -z "${vwpt+x}" ] || { vwp=yes; vmag=yes; } [ -z "${hypt+x}" ] || hyp=yes [ -z "${tupt+x}" ] || tup=yes [ -z "${xhpt+x}" ] || xhp=yes [ -z "${vxpt+x}" ] || vxp=yes [ -z "${anpt+x}" ] || anp=yes [ -z "${sspt+x}" ] || ssp=yes [ -z "${arpt+x}" ] || arp=yes [ -z "${sopt+x}" ] || sop=yes [ -z "${warp+x}" ] || wap=yes if find /proc/*/exe -type l 2>/dev/null | grep -E '/proc/[0-9]+/exe' | xargs -r readlink 2>/dev/null | grep -Eq 'agsbx/(s|x)' || pgrep -f 'agsbx/(s|x)' >/dev/null 2>&1; then if [ "$1" = "rep" ]; then [ "$vwp" = yes ] || [ "$sop" = yes ] || [ "$vxp" = yes ] || [ "$ssp" = yes ] || [ "$vlp" = yes ] || [ "$vmp" = yes ] || [ "$hyp" = yes ] || [ "$tup" = yes ] || [ "$xhp" = yes ] || [ "$anp" = yes ] || [ "$arp" = yes ] || { echo "ERROR: 请至少设置一个协议变量"; exit; } fi else [ "$1" = "del" ] || [ "$vwp" = yes ] || [ "$sop" = yes ] || [ "$vxp" = yes ] || [ "$ssp" = yes ] || [ "$vlp" = yes ] || [ "$vmp" = yes ] || [ "$hyp" = yes ] || [ "$tup" = yes ] || [ "$xhp" = yes ] || [ "$anp" = yes ] || [ "$arp" = yes ] || { echo "ERROR: 未安装脚本"; exit; } fi export uuid=${uuid:-''} export port_vl_re=${vlpt:-''} export port_vm_ws=${vmpt:-''} export port_vw=${vwpt:-''} export port_hy2=${hypt:-''} export port_tu=${tupt:-''} export port_xh=${xhpt:-''} export port_vx=${vxpt:-''} export port_an=${anpt:-''} export port_ar=${arpt:-''} export port_ss=${sspt:-''} export port_so=${sopt:-''} v46url="https://icanhazip.com" showmode(){ echo "==========================================" echo "快捷命令" echo "==========================================" echo "显示节点: cat /root/agsbx/jhsub.txt" echo "重置配置: agsbx rep" echo "卸载脚本: agsbx del" echo "更新Xray: agsbx upx" echo "更新Sing: agsbx ups" echo "重启服务: agsbx res" echo "查看状态: agsbx list" echo "==========================================" } echo "" echo "==========================================" echo "Sing-box Xray 官方脚本" echo "版本: V1.0.0" echo "==========================================" echo "" hostname=$(uname -a | awk '{print $2}') op=$(cat /etc/os-release 2>/dev/null | grep PRETTY_NAME | cut -d'"' -f2) case $(uname -m) in arm64|aarch64) cpu=arm64;; amd64|x86_64) cpu=amd64;; *) echo "ERROR: 不支持此架构"; exit 1 esac if [ "$1" != "del" ]; then mkdir -p "$HOME/agsbx" if [ ! -f "$HOME/agsbx/update" ]; then echo "INFO: 安装依赖..." if command -v apt >/dev/null 2>&1; then apt update -qq && apt install -y curl wget unzip tar >/dev/null 2>&1 fi touch "$HOME/agsbx/update" echo "OK: 依赖安装完成" fi fi v4v6(){ v4=$(curl -s4m5 -k "$v46url" 2>/dev/null) v6=$(curl -s6m5 -k "$v46url" 2>/dev/null) } upxray(){ echo "INFO: 下载Xray..." XRAY_VER=$(curl -s https://api.github.com/repos/XTLS/Xray-core/releases/latest | grep tag_name | cut -d'"' -f4 | sed 's/^v//') url="https://github.com/XTLS/Xray-core/releases/download/v${XRAY_VER}/Xray-linux-$cpu.zip" out="$HOME/agsbx/xray.zip" curl -Lo "$out" "$url" 2>/dev/null if [ -f "$out" ]; then unzip -o "$out" -d "$HOME/agsbx/" xray >/dev/null 2>&1 rm "$out" chmod +x "$HOME/agsbx/xray" echo "OK: Xray安装完成 版本: $XRAY_VER" else echo "ERROR: 下载失败" return 1 fi } upsingbox(){ echo "INFO: 下载Sing-box..." SB_VER=$(curl -s https://api.github.com/repos/SagerNet/sing-box/releases/latest | grep tag_name | cut -d'"' -f4 | sed 's/^v//') url="https://github.com/SagerNet/sing-box/releases/download/v${SB_VER}/sing-box-${SB_VER}-linux-$cpu.tar.gz" out="$HOME/agsbx/sing-box.tar.gz" curl -Lo "$out" "$url" 2>/dev/null if [ -f "$out" ]; then tar -xzf "$out" -C "$HOME/agsbx/" sing-box >/dev/null 2>&1 rm "$out" chmod +x "$HOME/agsbx/sing-box" echo "OK: Sing-box安装完成 版本: $SB_VER" else echo "ERROR: 下载失败" return 1 fi } status(){ echo "" echo "==========================================" echo "内核状态" echo "==========================================" if pgrep -f 'agsbx/s' >/dev/null 2>&1; then echo "RUNNING: Sing-box" else echo "STOPPED: Sing-box" fi if pgrep -f 'agsbx/x' >/dev/null 2>&1; then echo "RUNNING: Xray-core" else echo "STOPPED: Xray-core" fi if pgrep -f 'agsbx/c' >/dev/null 2>&1; then echo "RUNNING: Cloudflared" else echo "STOPPED: Cloudflared" fi echo "==========================================" } cip(){ echo "INFO: 检测IP..." v4v6 echo "" status echo "" echo "==========================================" echo "服务器IP" echo "==========================================" [ -z "$v4" ] && echo "IPv4: 无" || echo "IPv4: $v4" [ -z "$v6" ] && echo "IPv6: 无" || echo "IPv6: $v6" echo "==========================================" } cleandel(){ pkill -f 'agsbx/s' 2>/dev/null pkill -f 'agsbx/x' 2>/dev/null pkill -f 'agsbx/c' 2>/dev/null sed -i '/agsbx/d' ~/.bashrc 2>/dev/null crontab -l 2>/dev/null | sed '/agsbx/d' | crontab - 2>/dev/null rm -rf "$HOME/bin/agsbx" "$HOME/agsbx" if pidof systemd >/dev/null 2>&1; then systemctl stop xr sb argo 2>/dev/null systemctl disable xr sb argo 2>/dev/null rm -f /etc/systemd/system/{xr,sb,argo}.service systemctl daemon-reload 2>/dev/null fi } xrestart(){ pkill -f 'agsbx/x' 2>/dev/null sleep 1 systemctl restart xr 2>/dev/null || nohup $HOME/agsbx/xray run -c $HOME/agsbx/xr.json >/dev/null 2>&1 & echo "OK: Xray已重启" } sbrestart(){ pkill -f 'agsbx/s' 2>/dev/null sleep 1 systemctl restart sb 2>/dev/null || nohup $HOME/agsbx/sing-box run -c $HOME/agsbx/sb.json >/dev/null 2>&1 & echo "OK: Sing-box已重启" } if [ "$1" = "del" ]; then echo "INFO: 卸载中..." cleandel echo "OK: 卸载完成" exit 0 elif [ "$1" = "rep" ]; then echo "INFO: 重置中..." cleandel rm -rf "$HOME/agsbx"/{sb.json,xr.json} echo "OK: 重置完成" exit 0 elif [ "$1" = "list" ]; then cip exit 0 elif [ "$1" = "upx" ]; then upxray && xrestart && sleep 2 && cip exit 0 elif [ "$1" = "ups" ]; then upsingbox && sbrestart && sleep 2 && cip exit 0 elif [ "$1" = "res" ]; then echo "INFO: 重启中..." xrestart sbrestart sleep 3 echo "OK: 重启完成" cip exit 0 fi echo "==========================================" echo "系统信息" echo "==========================================" echo "操作系统: $op" echo "CPU架构: $cpu" echo "主机名: $hostname" echo "OK: 准备就绪" echo "" showmode
